{
    internal readonly Id _c1, _c2, _c3, _c4, _c5, _c6, _c7, _c8, _c9, _c10;

    private static Id[] BuildWith(World w)
    {
        var ids = new[] {
            (Id)w.Component<T1>(), (Id)w.Component<T2>(), (Id)w.Component<T3>(), (Id)w.Component<T4>(), (Id)w.Component<T5>(), (Id)w.Component<T6>(), (Id)w.Component<T7>(), (Id)w.Component<T8>(), (Id)w.Component<T9>(), (Id)w.Component<T10>()
        };
        Id[] result = Array.Empty<Id>();
        for (int i = 0; i < ids.Length; i++) result = QueryUtil.AppendSorted(result, ids[i]);
        return result;
    }

    internal Query(World w) : base(w, BuildWith(w))
    {
        _c1 = (Id)w.Component<T1>();
        _c2 = (Id)w.Component<T2>();
        _c3 = (Id)w.Component<T3>();
        _c4 = (Id)w.Component<T4>();
        _c5 = (Id)w.Component<T5>();
        _c6 = (Id)w.Component<T6>();
        _c7 = (Id)w.Component<T7>();
        _c8 = (Id)w.Component<T8>();
        _c9 = (Id)w.Component<T9>();
        _c10 = (Id)w.Component<T10>();
    }

    public Query<T1, T2, T3, T4, T5, T6, T7, T8, T9, T10> With<T>() where T : struct { AddWith(_world.IdOf<T>()); return this; }
    public Query<T1, T2, T3, T4, T5, T6, T7, T8, T9, T10> With(Id id) { AddWith(id); return this; }
